class Solution:

	def maximumMatch(self, G):
		M = len(G)
		N = len(G[0])
		ans = self.fun(G, M, N)
		return ans

	def fun(self, G, M, N):
		match = [-1 for i in range(N)]
		res = 0
		for u in range(M):
			seen = [False for i in range(N)]
			if self.bpm(G, u, seen, match, M, N):
				res += 1
		return res

	def bpm(self, G, u, seen, match, M, N):
		for v in range(N):
			if G[u][v] == 1 and (not seen[v]):
				seen[v] = True
				if match[v] < 0 or self.bpm(G, match[v], seen, match, M, N):
					match[v] = u
					return True
		return False
